package com.sphere.core.clhep.geometry;

import com.sphere.core.hepmc3.cxx.COStream;

/**
 * CLHEP's HepGeom::Plane3D&lt;double&gt; (Geometry/Plane3D.h, Plane3D.cc): the plane a x + b y + c z + d = 0.
 * Generated by gen_geometry.py.
 */
public class Plane3D {

    protected double a_;
    protected double b_;
    protected double c_;
    protected double d_;

    /** The plane z = 0. */
    public Plane3D() {
        a_ = 0;
        b_ = 0;
        c_ = 1;
        d_ = 0;
    }

    public Plane3D(double a1, double b1, double c1, double d1) {
        a_ = a1;
        b_ = b1;
        c_ = c1;
        d_ = d1;
    }

    /** The plane of normal n through p. */
    public Plane3D(Normal3D n, Point3D p) {
        a_ = n.x();
        b_ = n.y();
        c_ = n.z();
        d_ = n.negate().dot(p);
    }

    /** The plane through three points, its normal (p2-p1)x(p3-p1). */
    public Plane3D(Point3D p1, Point3D p2, Point3D p3) {
        final Normal3D n = new Normal3D(p2.minus(p1).cross(p3.minus(p1)));
        a_ = n.x();
        b_ = n.y();
        c_ = n.z();
        d_ = n.negate().dot(p1);
    }

    public Plane3D(Plane3D p) {
        a_ = p.a_;
        b_ = p.b_;
        c_ = p.c_;
        d_ = p.d_;
    }

    /** From a Plane3D&lt;float&gt;, widened. */
    public Plane3D(Plane3DF p) {
        a_ = p.a_;
        b_ = p.b_;
        c_ = p.c_;
        d_ = p.d_;
    }

    /** operator=. */
    public Plane3D assign(Plane3D p) {
        a_ = p.a_;
        b_ = p.b_;
        c_ = p.c_;
        d_ = p.d_;
        return this;
    }

    public double a() {
        return a_;
    }

    public double b() {
        return b_;
    }

    public double c() {
        return c_;
    }

    public double d() {
        return d_;
    }

    public Normal3D normal() {
        return new Normal3D(a_, b_, c_);
    }

    /** The coefficients divided by the length of the normal. */
    public Plane3D normalize() {
        final double ll = Math.sqrt(a_ * a_ + b_ * b_ + c_ * c_);
        if (ll > 0.) {
            a_ /= ll;
            b_ /= ll;
            c_ /= ll;
            d_ /= ll;
        }
        return this;
    }

    /** The signed distance of p (in units of the normal's length). */
    public double distance(Point3D p) {
        return a() * p.x() + b() * p.y() + c() * p.z() + d();
    }

    /** The projection of p on the plane. */
    public Point3D point(Point3D p) {
        final double k = distance(p) / (a() * a() + b() * b() + c() * c());
        return new Point3D(p.x() - a() * k, p.y() - b() * k, p.z() - c() * k);
    }

    /** The projection of the origin on the plane. */
    public Point3D point() {
        final double k = -d() / (a() * a() + b() * b() + c() * c());
        return new Point3D(a() * k, b() * k, c() * k);
    }

    public boolean isEqual(Plane3D p) {
        return a() == p.a() && b() == p.b() && c() == p.c() && d() == p.d();
    }

    public boolean notEqual(Plane3D p) {
        return a() != p.a() || b() != p.b() || c() != p.c() || d() != p.d();
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof Plane3D p && isEqual(p);
    }

    @Override
    public int hashCode() {
        return java.util.Objects.hash(a_, b_, c_, d_);
    }

    /** This plane transformed by m: its normal and a point of it. */
    public Plane3D transform(Transform3D m) {
        final Normal3D n = normal();
        n.transform(m);
        d_ = n.negate().dot(point().transform(m));
        a_ = n.x();
        b_ = n.y();
        c_ = n.z();
        return this;
    }

    /** operator&lt;&lt;: (a,b,c,d). */
    public COStream print(COStream os) {
        return os.put('(').put(a()).put(',').put(b()).put(',').put(c()).put(',').put(d()).put(')');
    }

    @Override
    public String toString() {
        return print(new COStream()).str();
    }
}
